  }
  stockQuantity
  rankingAlgorithm
  ...ProductCatalogItemPriceFragment
  variationProperties {
    ... on ProductCatalogItemScaledSizeVariationProperty {
      __typename
      order
      totalItems
      values {
        id
        order
        description
        __typename
      }
    }
    ... on ProductCatalogItemColorVariationProperty {
      __typename
      order
      totalItems
      values {
        id
        swatchImage {
          size54 {
            url
            alt
            __typename
          }
          __typename
        }
        __typename
      }
    }
    ... on ProductCatalogItemSizeVariationProperty {
      __typename
      order
      totalItems
      values {
        id
        description
        __typename
      }
    }
    __typename
  }
  visualizationExperience {
    isForMembers
    __typename
  }
  tags {
    id
    __typename
  }
  externalTriggers {
    type
    uri
    __typename
  }
  __typename
}

